CREATE OR REPLACE PROCEDURE sp(para_city_code VARCHAR2, para_Sex VARCHAR2, para_Secretary_Vote NUMBER, para_StuID NUMBER) IS
 CURSOR ref_cursor IS SELECT * FROM "Student" FOR UPDATE;
 rec "Student"%ROWTYPE;
 CURSOR ref_cursor2 IS SELECT * FROM "Voting_record" FOR UPDATE;
 rec2 "Voting_record"%ROWTYPE;
 v_student_exists NUMBER;
 v_student_updates NUMBER := 0;
BEGIN
 SELECT COUNT(*) INTO v_student_exists FROM "Student" WHERE {SLOT_1};
 OPEN ref_cursor;
 LOOP
  FETCH ref_cursor INTO rec;
  EXIT WHEN ref_cursor%NOTFOUND;
  IF {SLOT_2} THEN
   UPDATE "Student" SET "Sex" = {SLOT_3} WHERE CURRENT OF ref_cursor;
   v_student_updates := {SLOT_4};
  END IF;
 END LOOP;
 CLOSE ref_cursor;
 OPEN ref_cursor2;
 LOOP
  FETCH ref_cursor2 INTO rec2;
  EXIT WHEN ref_cursor2%NOTFOUND;
  IF {SLOT_5} THEN
   UPDATE "Voting_record" SET "StuID" = {SLOT_6} WHERE CURRENT OF ref_cursor2;
  END IF;
 END LOOP;
 CLOSE ref_cursor2;
END;

