CREATE OR REPLACE PROCEDURE sp(para_city_code VARCHAR2, para_Sex VARCHAR2, para_Secretary_Vote NUMBER, para_StuID NUMBER) IS
 CURSOR ref_cursor IS SELECT * FROM "Student" FOR UPDATE;
 rec "Student"%ROWTYPE;
 CURSOR ref_cursor2 IS SELECT * FROM "Voting_record" FOR UPDATE;
 rec2 "Voting_record"%ROWTYPE;
 v_student_exists NUMBER;
 v_student_updates NUMBER := 0;
BEGIN
 SELECT COUNT(*) INTO v_student_exists FROM "Student" WHERE "StuID" = para_StuID;
 OPEN ref_cursor;
 LOOP
  FETCH ref_cursor INTO rec;
  EXIT WHEN ref_cursor%NOTFOUND;
  IF rec."city_code" = para_city_code THEN
   UPDATE "Student" SET "Sex" = para_Sex WHERE CURRENT OF ref_cursor;
   v_student_updates := v_student_updates + 1;
  END IF;
 END LOOP;
 CLOSE ref_cursor;
 OPEN ref_cursor2;
 LOOP
  FETCH ref_cursor2 INTO rec2;
  EXIT WHEN ref_cursor2%NOTFOUND;
  IF rec2."Secretary_Vote" = para_Secretary_Vote AND v_student_exists > 0 AND v_student_updates > 0 THEN
   UPDATE "Voting_record" SET "StuID" = para_StuID WHERE CURRENT OF ref_cursor2;
  END IF;
 END LOOP;
 CLOSE ref_cursor2;
END;
